"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["4285"],{5360(e,t,a){a.r(t),a.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>l,assets:()=>c});var s=JSON.parse('{"id":"m12-gateway-trust/quiz","title":"Quiz: Gateway, Evals & Guardrails \u2014 Trust","description":"Check your grasp of the module: why a self-hosted budget stays at zero until you price it (and why the check is on the next request), how the eval gate turns the M5 golden set into an exit code that blocks a promotion, why a guardrail is a classifier with errors in both directions, the silent-no-op injection config, and reading per-key spend \u2014 including the tokens a thinking model bills but never shows.","source":"@site/docs/m12-gateway-trust/quiz.mdx","sourceDirName":"m12-gateway-trust","slug":"/m12-gateway-trust/quiz","permalink":"/305-llmops/docs/m12-gateway-trust/quiz","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Quiz: Gateway, Evals & Guardrails \u2014 Trust"},"sidebar":"courseSidebar","previous":{"title":"Lab: Trust \u2014 Front the Platform with a Gateway, Gate on Evals, Guardrail the Door","permalink":"/305-llmops/docs/m12-gateway-trust/lab"},"next":{"title":"Deep Dive (Part 2)","permalink":"/305-llmops/docs/m12-gateway-trust/deep-dive"}}'),o=a(4848),n=a(8453),i=a(7517);let r={sidebar_position:3,title:"Quiz: Gateway, Evals & Guardrails \u2014 Trust"},h="Gateway, Evals & Guardrails \u2014 Quiz",c={},l=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"gateway-evals--guardrails--quiz",children:"Gateway, Evals & Guardrails \u2014 Quiz"})}),"\n",(0,o.jsx)(t.p,{children:"Check your grasp of the module: why a self-hosted budget stays at zero until you price it (and why the check is on the next request), how the eval gate turns the M5 golden set into an exit code that blocks a promotion, why a guardrail is a classifier with errors in both directions, the silent-no-op injection config, and reading per-key spend \u2014 including the tokens a thinking model bills but never shows."}),"\n",(0,o.jsx)(i.A,{questions:[{prompt:"You mint a virtual key with max_budget: 5 against your self-hosted OpsMate model, send a hundred requests, and the key's spend still reads 0.0 \u2014 the budget never trips. What is happening, and what is the fix?",options:[{text:"A self-hosted model has no price in LiteLLM's map, so every call costs 0.0 \u2014 the tab never accrues and the budget gate can never fire. Set input_cost_per_token / output_cost_per_token on the model (a stand-in for real infra cost) so requests cost something and the budget can trip.",correct:!0,explanation:"Correct \u2014 the $0-cost lie. LiteLLM prices the commercial providers, not your Ollama model, so cost defaults to zero. A budget without a price is decoration; pricing your own infra is what makes the gate real. Verify it the lab way: three calls, then read the tab."},{text:"The budget is too high \u2014 lower max_budget to 0 and it will start enforcing.",correct:!1,explanation:"A budget of 0 would reject everything, but it does not fix the root cause: at 0.0 per token, ANY budget above 0 never trips because spend never accrues. The problem is the missing price, not the budget size."},{text:"Virtual keys do not track spend for self-hosted models at all; you must use the master key.",correct:!1,explanation:"Keys track spend fine \u2014 the spend is genuinely zero because the model is priced at zero. Once you set per-token costs, the same virtual key accrues spend and enforces its budget. The master key would not change the pricing."},{text:"Postgres is not recording the spend row; restart the database.",correct:!1,explanation:"If Postgres were down, /key/generate would fail outright \u2014 you would not have a working key. The row exists and reads 0.0 because the priced cost of each call is 0.0, not because it was not recorded."}]},{prompt:'You ask the gateway to "Reply with exactly: GATEWAY OK" and the usage block reports completion_tokens: 123 for a three-word answer. Why, and what does it mean for how you size budgets?',options:[{text:"Qwen3 is a thinking model \u2014 it generates hidden reasoning tokens before the visible answer, and the gateway's accounting counts them. You get billed for tokens you never see, so size budgets for what the model thinks, not just what it says.",correct:!0,explanation:"Correct \u2014 the M2 lesson at the gateway tier. The hidden reasoning is real generated tokens; the meter counts them. Push max_tokens low and you can get empty visible content whose completion_tokens is the full cap \u2014 the model spent its budget thinking. Budgets tuned to visible length trip early."},{text:"The gateway double-counts tokens as a billing bug; 123 is wrong for three words.",correct:!1,explanation:'It is not a bug \u2014 the count is honest. The model genuinely generated ~123 tokens of hidden reasoning before writing "GATEWAY OK". The CPU-seconds were spent, so the tab reflects them.'},{text:"completion_tokens counts the prompt, not the answer \u2014 123 is the size of your input.",correct:!1,explanation:"prompt_tokens counts the input; completion_tokens counts what decode wrote, which here includes the hidden reasoning. The two are separate fields in the usage block."},{text:"The number is padding the gateway adds so budgets trip sooner; disable it.",correct:!1,explanation:"There is no padding \u2014 the tokens are the model's actual reasoning output. There is nothing to disable; the honest response is to account for thinking tokens when you set budgets."}]},{prompt:'Your teammate says "we added a prompt_injection_params block to the gateway config, so injection is handled." You send an obvious "ignore previous instructions" attack and it sails straight through to the model. What is the most likely cause?',options:[{text:"prompt_injection_params only CONFIGURES the check; the check only RUNS if detect_prompt_injection is registered in callbacks. Params without the callback is a silent no-op \u2014 the config looks armed and inspects nothing.",correct:!0,explanation:'Correct \u2014 the silent-no-op exhibit. Registration (callbacks) and configuration (params) are two separate things; the params are inert without the callback. This is why "configured" and "running" are different claims, and why you verify a guardrail behaviorally \u2014 with a test attack \u2014 not by reading the YAML.'},{text:"The attack was too obvious; the heuristic only catches subtle injections.",correct:!1,explanation:'Backwards \u2014 an obvious "ignore previous instructions" is exactly what the heuristic is tuned to catch when the callback is registered. If a blatant attack passes, the check is not running, which points at the missing callback.'},{text:"Injection detection runs post_call, so it only flags the response, not the request.",correct:!1,explanation:"detect_prompt_injection inspects the incoming request and rejects before the model runs. The reason it did nothing here is that it was never invoked (no callback registered), not that it ran at the wrong time."},{text:"The gateway masks injections as PII, so the attack was silently rewritten.",correct:!1,explanation:"PII masking and injection detection are separate guardrails. Masking rewrites names/emails/phones; it does not neutralize an injection instruction. The attack passed because the injection callback was not registered."}]},{prompt:'During the red-team run, a DIRECT injection in the user turn is blocked, but the INDIRECT M4 payload \u2014 the poisoned runbook text replayed as retrieved content \u2014 gets through and steers the answer to "ROLLBACK". Why the difference, and what does it tell you?',options:[{text:"The injection heuristic is tuned for attacks in the user's message; a payload that arrives as retrieved content reads as ordinary context and slips it. The gap is a real finding \u2014 defending the indirect case needs source allow-listing and corpus write-governance, not just the door heuristic.",correct:!0,explanation:"Correct \u2014 and it is the honest result the module is built around. Same hook, different attack surface: the user turn is inspected, the retrieved content is not. A single heuristic at the door does not solve indirect (content-borne) injection; that is why M4's tagged-source template alone was never enough, and why real defense governs the corpus."},{text:"The indirect payload is simply a stronger attack the model cannot resist; nothing can stop it.",correct:!1,explanation:'It is not about attack strength \u2014 it is about attack surface. The direct attack was caught because the user turn is inspected. The fix is a different control (inspect/allow-list retrieved sources), not "give up".'},{text:"The red-team script has a bug \u2014 a THROUGH result means the test failed.",correct:!1,explanation:"A THROUGH is a finding, not a script failure. The script's job is to record what gets through so you can close the blind spot; an attack that lands is exactly the signal you ran it to find."},{text:'The gateway blocked the indirect attack too; the "ROLLBACK" answer is a coincidence.',correct:!1,explanation:'It is not a coincidence \u2014 "ROLLBACK" is the exact instruction the M4 payload plants. Getting that single word back is the injection succeeding, replayed from the M4 exhibit.'}]},{prompt:"You wire the M5 golden set as a promotion gate (gate.sh). Which statements about how the gate works are true? (Select all that apply.)",options:[{text:"gate.sh scores the generation layer deterministically against the assistant's /ask and compares the pass count to the floor committed in baseline.md \u2014 at or above the floor it exits 0 and promotion proceeds; below it, exit 1 blocks the merge.",correct:!0,explanation:"Correct. This is the contract: a threshold against the committed baseline, scored deterministically. The floor sits between the measured RAG and no-RAG arms, so the gate enforces exactly the value of retrieval the baseline measured."},{text:"The eval runs against the gateway /v1 with a virtual key, so the eval traffic passes through the same guardrails and accounting as production.",correct:!1,explanation:"False \u2014 this is the exhibit the lab refutes. Routing the eval through the guarded door lets the PII mask mangle eval content (Kafka masked as a person) and strips retrieval from the path. Eval traffic is internal: the gate hits /ask directly \u2014 retrieval in, mask out of the way."},{text:"Raw promptfoo's exit code (0 all-green / 100 on any fail) is a sufficient gate contract on its own.",correct:!1,explanation:'False \u2014 the naive design\'s real bug. A healthy small model never goes all-green on a wide golden set, so raw promptfoo calls a healthy assistant "red" every run. The gate thresholds the pass count against the committed floor instead.'},{text:"On the 8 GB path the gate runs as a local dry-run of the same gate.sh a CI runner executes; the full in-cluster replay is the 16 GB / cluster path.",correct:!0,explanation:"Correct. The gate's logic is fully proven on 8 GB by running gate.sh locally against the Compose-phase assistant. Co-residency with a live cluster (all heavyweight tenants at once) is the 16 GB path."},{text:"The gate replaces the M11 promotion PR \u2014 you no longer open a pull request, you just run the eval.",correct:!1,explanation:"False. The PR is the mechanism (M11); the eval is the permission (M12). Promotion is a pull request AND a passing eval \u2014 the gate blocks the merge, it does not remove it."}],multiSelect:!0},{prompt:'A guardrail masks a real @gmail.com address correctly, but lets a @corp.example address through unmasked, and separately redacts the ops ticket number "4491" as <DATE_TIME>. How should you think about these two behaviors?',options:[{text:"A guardrail is a classifier with error rates in both directions: the .example miss is a false negative (blind spot) and the ticket-number redaction is a false positive (over-fire). Both are expected, both cost you, and both must be measured \u2014 you test guardrails like any other model, not install and assume.",correct:!0,explanation:"Correct \u2014 the airport-security framing. The scanner misses real threats and stops harmless things, every day. The false positive is the operational sting: over-redacting the ticket number hides the identifier on-call work needs. You red-team both directions rather than trusting the door is safe."},{text:"Both are bugs in Presidio that a version upgrade will fix; guardrails should be perfect.",correct:!1,explanation:'Guardrails are classifiers and no classifier is perfect \u2014 there is no version that eliminates both false negatives and false positives. Treating "install the guardrail" as "the door is safe" is exactly the mistake the module warns against.'},{text:"The .example miss proves masking is useless; turn it off.",correct:!1,explanation:"One blind spot does not make masking useless \u2014 it caught the real gmail address. The lesson is to measure the blind spots and add recognizers, not to remove a control that works most of the time."},{text:"The ticket-number over-fire is harmless because over-redaction is always safe.",correct:!1,explanation:'Over-redaction is not harmless here \u2014 masking "4491" as a date corrupts operational data, so the model can no longer see the ticket number it needs to help. A false positive degrades the assistant\'s usefulness; both error directions have a cost.'}]},{prompt:'The red-team run reports attack [2] (the M4 corpus payload, replayed verbatim) as BLOCKED, but attack [3] \u2014 the SAME hijack intent, rephrased to drop "Context follows" / "do not cite any runbook" \u2014 comes back http=200, THROUGH. What is the honest reading of this pair?',options:[{text:"detect_prompt_injection is a template matcher: it fires on known attack PHRASINGS, not on meaning. [2] was blocked by luck because the M4 payload carries listed fragments; [3] avoids them and sails through. A paraphrase defeats the door, which is why real defense governs the corpus, not just the string matcher.",correct:!0,explanation:"Correct \u2014 the sharpened result. The block in [2] is phrase-matching, not comprehension. Rephrasing the identical intent past the phrase list is the false-negative direction of a classifier, live. The fix is source allow-listing and corpus write-governance, not trusting one matcher at the door."},{text:"[2] being blocked proves the indirect case is handled; [3] getting through is a separate, unrelated bug.",correct:!1,explanation:"They are the same finding, not two. Both are the indirect/content path; [2] blocked only because it happened to carry trigger phrasings, and [3] shows what the same matcher misses the moment an attacker rewrites the payload."},{text:"The heuristic understood [2] was dangerous and reasoned that [3] was safe.",correct:!1,explanation:"No comprehension is involved \u2014 it is pure string similarity against a phrase list. It matched [2]'s phrasing and missed [3]'s; meaning never entered into it."},{text:"[3] is a stronger attack the model simply cannot resist, so nothing at the gateway could stop it.",correct:!1,explanation:"It is not about attack strength \u2014 [2] and [3] carry identical intent. The difference is phrasing versus the template list. A meaning-aware control or corpus governance would catch [3]; a string matcher at the door cannot."}]},{prompt:'You mint a key with max_budget: 0.00005 against the PRICED opsmate route. Request one ("hello") is accepted and comes back \u2014 even though its cost pushes the tab past the budget. Request two is rejected with "Budget has been exceeded!". Why does the crossing request succeed? (Deep Dive)',options:[{text:"The budget check reads ACCRUED spend \u2014 the total before this request \u2014 and compares it to max_budget. Request one arrived at spend 0.0 (under budget), ran, and accrued its cost; request two arrived already over and was rejected before running. The gate stops the NEXT request, not the one that crosses the line.",correct:!0,explanation:"Correct \u2014 stage 4 of the cost-accounting path. You cannot know a request's exact cost until decode finishes, so a hard mid-request cap is impractical. max_budget is the spend at which the key stops accepting NEW work, not a ceiling the total can never exceed. Size it with one call's headroom."},{text:"Request one was free (cached) and request two was the first real charge.",correct:!1,explanation:"Both were real, priced calls \u2014 request one accrued its cost (in the live run ~0.000079 against a 0.00005 budget). Caching is a different mechanism; the ordering here is that the check reads spend accrued BEFORE the current request."},{text:"LiteLLM refunds request one's cost, so only request two counts against the budget.",correct:!1,explanation:"There is no refund. Request one's cost is added to the row and stays there; that accrued total is exactly what makes request two arrive already over budget."},{text:"The budget only applies once max_tokens is exhausted, which happened on request two.",correct:!1,explanation:"max_tokens caps a single response length; it is unrelated to the budget check. The budget compares accrued spend to max_budget at admission time, which is why the crossing request runs and the next one is refused."}]},{prompt:'A colleague wants to "make gate.sh strict" by having it return the raw promptfoo score (e.g. exit 100 when any assertion fails) instead of a pass/fail exit code. Why is this the wrong contract for the promotion gate?',options:[{text:'gate.sh\'s contract is an exit CODE \u2014 0 (at/above the committed baseline floor \u2192 promote) or 1 (below \u2192 block) \u2014 not a raw score. Raw promptfoo exits non-zero on ANY failed assertion, and a healthy 0.6B model never scores all-green on a wide golden set, so the raw code calls a healthy assistant "red" every run. That is a flake, not a gate.',correct:!0,explanation:"Correct. The gate thresholds the deterministic pass count against baseline.md's floor (8, sitting between the ~11/12 RAG and ~6/12 no-RAG arms) and emits a binary exit code the pipeline branches on. A raw score cannot separate healthy from regressed; the floored exit code can."},{text:"A raw score of 100 is a perfect pass, so exiting 100 would let every promotion through \u2014 too permissive.",correct:!1,explanation:"Backwards on two counts: promptfoo's non-zero exit signals FAILURE, not perfection, and the real problem is that it fires on any single miss. The gate's job is a floored exit code, not any numeric score interpreted as quality."},{text:"Exit codes above 125 are reserved by the shell, so 100 is fine but 137 would break \u2014 it is a numbering issue.",correct:!1,explanation:"The objection is not about which integers are legal exit codes. It is that a gate must be a pass/fail decision against the committed floor; a raw per-assertion score, whatever its value, cannot distinguish a healthy small model from a regressed one."},{text:"promptfoo scores are non-deterministic, so any exit code from it flakes; gate.sh should average three runs into a score.",correct:!1,explanation:"The deterministic contains_any layer that gate.sh scores IS reproducible \u2014 that is why the gate keys on it and demotes the flaky judge to advisor. The fix is a floored exit code on the deterministic layer, not averaging scores."}]},{prompt:"Someone points OpenAI-compatible clients at the gateway with model: opsmate-dead (a route whose backend has nothing listening) and is surprised to still get answers. Reading the response, the model field says ollama/qwen25-1.5b-16k. What happened, and why does the model field matter operationally?",options:[{text:'The primary route failed, so the gateway retried against its named fallback and answered from qwen25-1.5b-16k. The response\'s model field names the SUBSTITUTE that actually served \u2014 the honest tell that lets you answer "why does this answer look different" during an incident by reading which model served.',correct:!0,explanation:"Correct \u2014 fallback, and its honest tell. A single backend is a single point of failure; the standing fallback answers when the primary cannot. The model field naming the substitute (not the alias you asked for) is what the gateway records so you can trace a differently-shaped answer to the model that produced it."},{text:"The gateway cached a prior opsmate answer and replayed it, which is why a dead route still responded.",correct:!1,explanation:"A cache hit replays an identical prior request and is tagged cache_hit; here a different model (the fallback) served, named in the model field. Fallback and caching are separate house rules in the request path."},{text:"opsmate-dead silently rerouted to the primary opsmate model, so the model field is just showing the primary.",correct:!1,explanation:"The field names qwen25-1.5b-16k, the FALLBACK, not the opsmate primary. The lesson is that the gateway records the substitute honestly rather than pretending the requested route served."},{text:'Nothing failed \u2014 "dead" routes always work; the model field is cosmetic and can be ignored.',correct:!1,explanation:"The route genuinely had nothing listening; the answer came from the fallback. The model field is the opposite of cosmetic \u2014 in an incident it is how you learn which model actually served a suspicious answer."}]},{prompt:"Which of these correctly describe how the gateway's guardrails behave in THIS module's lab and Deep Dive? (Select all that apply.)",options:[{text:"PII masking is a pre_call hook: Presidio rewrites detected entities to placeholders BEFORE the model or any log sees the raw value \u2014 masking on the way in is the only ordering that keeps the model from ever seeing the secret.",correct:!0,explanation:"Correct. The whole value of masking is that the model and downstream logs never see the raw name/email/phone, which only holds if the rewrite happens pre_call. Run it post_call and you have already leaked to the model before scrubbing the response."},{text:"The .example email passing through unmasked while a @gmail.com address on the same request is caught is a false negative (a recognizer blind spot) \u2014 an input-direction miss you only find by testing the edges.",correct:!0,explanation:"Correct. A guardrail is a classifier with errors in both directions; the .example miss is the false-negative direction, found by red-teaming the edges, not by trusting the door is safe."},{text:'Redacting the ops ticket number "4491" as <DATE_TIME> is harmless over-caution, because over-redaction is always safe.',correct:!1,explanation:"False. Over-redaction is the operational sting: masking 4491 as a date corrupts operational data, so the assistant can no longer see the ticket number on-call work runs on. A false positive degrades usefulness \u2014 both error directions cost you."},{text:"Setting prompt_injection_params without registering detect_prompt_injection in callbacks leaves the check inert: the config looks armed and inspects nothing, and the only way to detect it is behaviorally, with a test attack.",correct:!0,explanation:"Correct \u2014 the silent no-op. Configuration (params) and registration (callbacks) are separate; params without the callback fail open and quietly. You verify a guardrail by a blocked attack in a test, never by reading the YAML."},{text:"The gate corrupts because PII masking runs on the OUTPUT \u2014 moving the mask to pre_call would fix the eval-through-the-gateway corruption.",correct:!1,explanation:"False. The mask already runs pre_call; that is exactly why it mangles eval CONTENT on the way in (Kafka \u2192 <PERSON>, a window \u2192 <DATE_TIME>). The fix is not re-ordering the hook \u2014 it is not routing internal eval traffic through the production mask at all; the gate hits /ask directly."}],multiSelect:!0}]})]})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},7517(e,t,a){a.d(t,{A:()=>i});var s=a(4848),o=a(6540);function n({q:e,state:t,onToggle:a}){return(0,s.jsxs)("div",{className:"question_QpiT",children:[(0,s.jsx)("p",{className:"prompt_TqRJ",children:e.prompt}),e.multiSelect&&(0,s.jsx)("p",{className:"hint_e_F7",children:"(select all that apply)"}),(0,s.jsx)("ul",{className:"options_X9pq",children:e.options.map((e,o)=>{let n=t.selected.has(o),i="option_qGol";return t.checked?e.correct?i+=" correct_LYA5":n&&(i+=" incorrect_kRFc"):n&&(i+=" chosen_H3WG"),(0,s.jsxs)("li",{children:[(0,s.jsxs)("button",{type:"button",className:i,disabled:t.checked,onClick:()=>a(o),children:[(0,s.jsx)("span",{className:"marker_vN_w",children:n?"\u25CF":"\u25CB"})," ",e.text]}),t.checked&&(n||e.correct)&&e.explanation&&(0,s.jsx)("p",{className:"explanation_HBZ0",children:e.explanation})]},o)})})]})}function i({questions:e}){let[t,a]=(0,o.useState)(e.map(()=>({selected:new Set,checked:!1}))),r=t.every(e=>e.checked),h=t.filter((t,a)=>{var s,o;let n;return s=e[a],o=t.selected,n=s.options.map((e,t)=>e.correct?t:-1).filter(e=>e>=0),s.multiSelect?o.size===n.length&&[...o].every(e=>s.options[e].correct):1===o.size&&n.includes([...o][0])}).length;return(0,s.jsxs)("div",{className:"quiz_I014",children:[e.map((o,i)=>(0,s.jsx)(n,{q:o,state:t[i],onToggle:t=>a(a=>a.map((a,s)=>{if(s!==i)return a;let o=new Set(a.selected);return e[i].multiSelect?o.has(t)?o.delete(t):o.add(t):(o.clear(),o.add(t)),{...a,selected:o}}))},i)),(0,s.jsxs)("div",{className:"actions_XUwt",children:[(0,s.jsx)("button",{type:"button",className:"check_wZ2j",onClick:()=>a(e=>e.map(e=>({...e,checked:!0}))),children:"Check answers"}),(0,s.jsx)("button",{type:"button",className:"resetBtn_JHSa",onClick:()=>a(e.map(()=>({selected:new Set,checked:!1}))),children:"Reset"}),r&&(0,s.jsxs)("span",{className:"score_AN7p",children:["Score: ",h," / ",e.length]})]})]})}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>r});var s=a(6540);let o={},n=s.createContext(o);function i(e){let t=s.useContext(n);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(n.Provider,{value:t},e.children)}}}]);